/* ═══ HELPERS ═══ */
function hS(h){
  if(h.includes('院士'))return'院士';
  if(h.includes('长江学者特聘'))return'长江学者';
  if(h.includes('青年长江'))return'青年长江';
  if(h.includes('万人计划')&&h.includes('领军'))return'万人·领军';
  if(h.includes('万人计划')&&h.includes('创新'))return'万人·创新领军';
  if(h.includes('万人计划')&&h.includes('青年'))return'万人·青年拔尖';
  if(h.includes('万人计划'))return'万人计划';
  if(h.includes('万人计划教学名师'))return'万人计划教学名师';
  if(h.includes('国家杰出青年'))return'国家杰青';
  if(h.includes('国家优秀青年'))return'国家优青';
  if(h.includes('国务院特殊津贴'))return'国务院津贴';
  if(h.includes('东方学者')||h.includes('东方英才'))return'东方学者';
  if(h.includes('珠江学者'))return'珠江学者';
  if(h.includes('浦江学者')||h.includes('浦江人才'))return'浦江学者';
  if(h.includes('百千万人才'))return'百千万人才';
  if(h.includes('长江学者通讯'))return'长江通讯评审';
  if(h.includes('长江学者青年'))return'青年长江学者';
  if(h.includes('曙光学者'))return'上海曙光学者';
  if(h.includes('国家科技进步'))return'国家科技进步奖';
  if(h.includes('百人计划'))return'国家体总百人';
  if(h.includes('国家重点研发'))return'国重项目首席';
  if(h.includes('国家社科基金重大'))return'国社科重大首席';
  if(h.includes('重点实验室主任'))return'重点实验室主任';
  /* 省级特聘学者计划 */
  if(h.includes('楚天学者'))return'楚天学者';
  if(h.includes('泰山学者'))return'泰山学者';
  if(h.includes('天府学者'))return'天府学者';
  if(h.includes('芙蓉学者'))return'芙蓉学者';
  if(h.includes('三秦学者'))return'三秦学者';
  if(h.includes('燕赵学者'))return'燕赵学者';
  if(h.includes('钱江学者'))return'钱江学者';
  if(h.includes('赣鄱学者'))return'赣鄱学者';
  if(h.includes('闽江学者'))return'闽江学者';
  if(h.includes('中原学者'))return'中原学者';
  if(h.includes('龙江学者'))return'龙江学者';
  if(h.includes('云岭学者'))return'云岭学者';
  if(h.includes('天山学者'))return'天山学者';
  if(h.includes('长白山学者'))return'长白山学者';
  if(h.includes('草原英才'))return'草原英才';
  if(h.includes('南海学者'))return'南海学者';
  if(h.includes('巴渝学者'))return'巴渝学者';
  if(h.includes('黄河学者'))return'黄河学者';
  if(h.includes('海峡学者'))return'海峡学者';
  if(h.includes('桂派学者'))return'桂派学者';
  /* 其他省级人才 */
  if(h.includes('吉林省'))return'吉林省拔尖人才';
  if(h.includes('四川省'))return'省级带头人';
  if(h.includes('江苏'))return'江苏省人才';
  if(h.includes('广东省'))return'广东省人才';
  if(h.includes('辽宁省'))return'辽宁省百千万';
  if(h.includes('陕西省'))return'陕西省人才';
  if(h.includes('深圳市'))return'深圳高层次人才';
  if(h.includes('天津市'))return'天津市重点实验室';
  if(h.includes('国家级青年人才'))return'国家级青年人才';
  return h.length>14?h.slice(0,14)+'…':h;
}
function esc(t){return String(t==null?'':t).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
function realHats(s){return (s&&Array.isArray(s.hats))?s.hats:[];}
function hl(t){
  var x=esc(t);
  if(!q)return x;
  try{return x.replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<mark>$1</mark>');}catch(e){return x;}
}
function filt(){
  /* Fast path: opening 学者库 with no filters — skip full scan/alloc */
  if(!discGroup&&!disc&&!hat&&!inst&&!gender&&!cat&&!role&&!prov&&!q&&!sortMode)return S;
  var qLow=q?String(q).toLowerCase():'';
  var list=S.filter(s=>{
    if(discGroup&&GRAD_DISC_GROUPS[discGroup]&&!GRAD_DISC_GROUPS[discGroup].disc.includes(s.disc))return false;
    if(!discGroup&&disc&&s.disc!==disc)return false;
    if(hat&&!s.hats.concat(s.hon).some(h=>h.includes(hat)))return false;
    if(inst&&!s.institution.includes(inst))return false;
    if(gender&&(s.g===1?'male':s.g===0?'female':s.g)!==gender)return false;
    if(cat&&s.cat!==cat)return false;
    if(role&&s.role!==role)return false;
    if(prov&&_PROV_INST_SET[prov]&&!_PROV_INST_SET[prov].has(s.institution))return false;
    if(qLow){
      const hay=[s.n,s.e,s.institution,s.dept,s.r,s.dL,...s.hats,...s.hon,RL[s.role]||''].join(' ').toLowerCase();
      if(!hay.includes(qLow))return false;
    }
    return true;
  });
  if(sortMode==='name') list.sort((a,b)=>a.n.localeCompare(b.n,'zh'));
  else if(sortMode==='inst') list.sort((a,b)=>(_INST_COUNT[b.institution]||0)-(_INST_COUNT[a.institution]||0));
  else if(sortMode==='disc') list.sort((a,b)=>a.disc.localeCompare(b.disc));
  else if(sortMode==='hat') list.sort((a,b)=>(b.hats.length+b.hon.length)-(a.hats.length+a.hon.length));
  return list;
}


