/* PHD Render v2 */
let phdFilter='all';
const PRMAP={'A+':'Ap','A':'A','A-':'Am','B+':'Bp','B':'B','B-':'Bm','C+':'Cp','C':'C','C-':'Cm'};

function renderPhdSchools(){
  const iCnt={};
  S.forEach(s=>{iCnt[s.institution]=(iCnt[s.institution]||0)+1;});
  PHD_INSTS.forEach(p=>{p.scholars=iCnt[p.n]||0;});
  const e1=document.getElementById('phdTotal');
  const e2=document.getElementById('phdDual');
  const dualCnt=PHD_INSTS.filter(p=>p.phdAcad&&p.phdProf).length;
  if(e1) e1.textContent=PHD_INSTS.length+'所';
  if(e2) e2.textContent=dualCnt+'所';
  const tabs=document.getElementById('phdTabs');
  if(tabs&&!tabs.dataset.init){
    tabs.dataset.init='1';
    const pc=PHD_INSTS.filter(p=>!p.phdAcad&&p.phdProf).length;
    const btnDefs=[
      ['all','全部 ('+PHD_INSTS.length+')'],
      ['dual','🔵 双授权 ('+dualCnt+')'],
      ['prof','🟡 仅专博 ('+pc+')'],
      ['华北','华北'],['华东','华东'],['华中','华中'],
      ['华南','华南'],['西南','西南'],['西北','西北'],['东北','东北']
    ];
    btnDefs.forEach(([v,l])=>{
      const b=document.createElement('button');
      b.className='phd-tab'+(v==='all'?' on':'');
      b.textContent=l;
      b.onclick=(function(vv,bb){return function(){
        phdFilter=vv;
        tabs.querySelectorAll('.phd-tab').forEach(x=>x.classList.remove('on'));
        bb.classList.add('on');
        phdDraw();
      };})(v,b);
      tabs.appendChild(b);
    });
  }
  phdDraw();
}

function phdDraw(){
  const el=document.getElementById('phdContent');
  if(!el) return;
  let list=PHD_INSTS.slice();
  if(phdFilter==='dual') list=list.filter(p=>p.phdAcad&&p.phdProf);
  else if(phdFilter==='prof') list=list.filter(p=>!p.phdAcad&&p.phdProf);
  else if(phdFilter!=='all') list=list.filter(p=>p.region===phdFilter);
  if(!list.length){el.innerHTML='<div class="phd-empty">暂无符合条件的院校</div>';return;}
  const ro={'A+':1,'A':2,'A-':3,'B+':4,'B':5,'B-':6,'C+':7,'C':8,'C-':9};
  const MS='font-size:.67rem;color:#5A6575';
  const groups=[
    {lb:'学术+专业 双授权（有第四轮学科评估等级）',
     it:list.filter(p=>p.phdAcad&&p.phdProf&&p.rank4).sort((a,b)=>(ro[a.rank4]||99)-(ro[b.rank4]||99))},
    {lb:'学术+专业 双授权（2018年后新增，第四轮仅硕士或未参评）',
     it:list.filter(p=>p.phdAcad&&p.phdProf&&!p.rank4)},
    {lb:'仅专业学位博士点（0452，2024年全国首批）',
     it:list.filter(p=>!p.phdAcad&&p.phdProf)},
    {lb:'学术博士点（暂无专业博士授权）',
     it:list.filter(p=>p.phdAcad&&!p.phdProf)},
  ].filter(g=>g.it.length>0);
  el.innerHTML=groups.map(g=>{
    const cards=g.it.map(ins=>{
      const isDual=ins.phdAcad&&ins.phdProf;
      const isProf=!ins.phdAcad&&ins.phdProf;
      const cc='phd-card '+(isDual?'c-dual':isProf?'c-prof':'c-acad');
      const rc=ins.rank4?PRMAP[ins.rank4]:'';
      const rb=ins.rank4?'<span class="phd-rank-pill r'+rc+'">'+ins.rank4+'</span>':'';
      const ay=ins.phdAcad?'<span style="'+MS+'">学博'+ins.phdAcad+'年'+(ins.phdAcad>=2024?'<span class="pb-new"> 新增</span>':'')+'</span>':'';
      const py=ins.phdProf?'<span style="'+MS+'">专博'+ins.phdProf+'年</span>':'';
      const tb=isDual?'<span class="phd-badge pb-dual">⊕ 学术+专业双授权</span>'
               :isProf?'<span class="phd-badge pb-prof">🎓 专业博士（0452）</span>'
                      :'<span class="phd-badge pb-acad">📚 学术博士（0403）</span>';
      const sl=ins.scholars>0?'<span class="phd-lnk" style="cursor:pointer" onclick="filterToInst(\'' +ins.n+ '\')">'+ins.scholars+'位学者</span>':'';
      return '<div class="'+cc+'">'
        +'<div class="phd-card-top"><span class="phd-card-name" onclick="filterToInst(\'' +ins.n+ '\')">'+ins.n+'</span>'+rb+'</div>'
        +'<div class="phd-types">'+tb+ay+py+'</div>'
        +'<div class="phd-note">'+ins.note+'</div>'
        +'<div class="phd-links">'
        +'<a href="'+getInstUrl(ins.n)+'" target="_blank" rel="noopener" class="phd-lnk">🌐 学校/学院官网</a>'
        +'<a href="'+ins.szdwUrl+'" target="_blank" rel="noopener" class="phd-lnk">👨‍🏫 师资队伍</a>'
        +sl+'</div></div>';
    }).join('');
    return '<div class="phd-group-hd"><span>'+g.lb+'</span><span class="gcnt">'+g.it.length+'所</span></div>'
      +'<div class="phd-grid">'+cards+'</div>';
  }).join('');
}

function filterToInst(n){
  inst=n;q='';go('scholars');setTimeout(renderSc,100);
}


