var DS={};
function renderDiscLab(k){
  var c=DCFG[k];if(!c)return;
  var Ss=S.filter(function(s){return s.disc===k;});
  var eN=Ss.filter(function(s){return s.hats.length>0||s.hon.length>0;}).length;
  var iN=new Set(Ss.map(function(s){return s.institution;})).size;
  var u=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
  u("dlabDesc_"+k,Ss.length+"位学者 · "+iN+"所机构");
  u("dlabN_"+k,Ss.length);u("dlabE_"+k,eN);u("dlabI_"+k,iN+"所");
  if(!DS[k]) DS[k]={v:"topic",t:"all"};
  var br=document.getElementById("dlabBtns_"+k);
  if(br&&!br.dataset.init){
    br.dataset.init="1";
    [["topic","📄 子领域概览"],["elite","⭐ 精英学者"],["inst","🏛 机构排行"],["all","👥 全部浏览"]
    ].forEach(function(df){
      var b=document.createElement("button");
      b.className="dlab-btn";
      b.textContent=df[1];
      b.dataset.v=df[0];b.dataset.k=k;
      if(df[0]==="topic"){b.classList.add("on");b.style.cssText="background:"+c.color+"18;color:"+c.color+";border-color:"+c.color+"40";}
      b.addEventListener("click",function(){
        var kk=this.dataset.k,vv=this.dataset.v;
        DS[kk].v=vv;DS[kk].t="all";
        var pp=this.parentNode;
        pp.querySelectorAll(".dlab-btn").forEach(function(x){x.classList.remove("on");x.style.cssText="";});
        this.classList.add("on");
        this.style.cssText="background:"+DCFG[kk].color+"18;color:"+DCFG[kk].color+";border-color:"+DCFG[kk].color+"40";
        dlabDraw(kk);
      });
      br.appendChild(b);
    });
  }
  dlabDraw(k);
}
function dlabTopicClick(el){var k=el.dataset.k,t=el.dataset.t;DS[k].t=t;dlabDraw(k);}
function dlabInstClick(el){filterToInst(el.dataset.n);}
function dlabMatch(s,c,tid){
  if(tid==="all") return true;
  var t=c.subtopics.find(function(x){return x.id===tid;});
  if(!t||!t.keys) return true;
  var h=(s.r+" "+s.dept).toLowerCase();
  return t.keys.some(function(k){return h.includes(k.toLowerCase());});
}
function dlabDraw(k){
  var el=document.getElementById("dlabMain_"+k);if(!el)return;
  var c=DCFG[k],st=DS[k]||{v:"topic",t:"all"};
  var Ss=S.filter(function(s){return s.disc===k;});
  if(st.v==="topic") el.innerHTML=dTopic(Ss,c,st);
  else if(st.v==="elite") el.innerHTML=dElite(Ss,c);
  else if(st.v==="inst") el.innerHTML=dInst(Ss,c);
  else el.innerHTML=dAll(Ss,c);
}
function dTopic(Ss,c,st){
  var H="";
  c.subtopics.forEach(function(t){
    var cnt=Ss.filter(function(s){return dlabMatch(s,c,t.id);}).length;
    var sel=t.id===st.t;
    H+="<div class=\"dlab-topic-card\" data-k=\""+c.key+"\" data-t=\""+t.id+"\" onclick=\"dlabTopicClick(this)\"";
    if(sel) H+=" style=\"background:"+c.color+"18;border-color:"+c.color+"\"";
    H+="><div class=\"dlab-topic-icon\">"+t.icon+"</div>";
    H+="<div class=\"dlab-topic-name\">"+t.name+"</div>";
    H+="<div class=\"dlab-topic-cnt\" style=\"color:"+c.color+"\">"+cnt+"位学者</div>";
    H+="<div class=\"dlab-topic-desc\">"+t.desc+"</div></div>";
  });
  var cur=c.subtopics.find(function(t){return t.id===st.t;})||c.subtopics[0];
  var list=Ss.filter(function(s){return dlabMatch(s,c,st.t);})
    .sort(function(a,b){return (b.hats.length+b.hon.length)-(a.hats.length+a.hon.length);});
  var G="";
  list.forEach(function(s){G+=dCard(s,c.color);});
  return "<div class=\"dlab-topic-grid\">"+H+"</div>"
    +"<div class=\"dlab-sec-hd\"><h3>"+cur.icon+" "+cur.name+"</h3>"
    +"<span class=\"dlab-sec-badge\" style=\"color:"+c.color+";border-color:"+c.color+"40\">"+list.length+"位学者</span></div>"
    +"<div class=\"dlab-scholar-grid\">"+G+"</div>";
}
function dElite(Ss,c){
  var list=Ss.filter(function(s){return s.hats.length>0||s.hon.length>0;})
    .sort(function(a,b){return (b.hats.length+b.hon.length)-(a.hats.length+a.hon.length);});
  var G="";list.forEach(function(s){G+=dCard(s,c.color);});
  return "<div class=\"dlab-sec-hd\"><h3>⭐ 人才计划入选者</h3><span class=\"dlab-sec-badge\" style=\"color:"+c.color+";border-color:"+c.color+"40\">"+list.length+"位</span></div>"
    +"<div class=\"dlab-scholar-grid\">"+G+"</div>";
}
function dInst(Ss,c){
  var iM={};
  Ss.forEach(function(s){if(!iM[s.institution])iM[s.institution]={n:s.institution,cnt:0};iM[s.institution].cnt++;});
  var rows=Object.values(iM).sort(function(a,b){return b.cnt-a.cnt;});
  var mx=rows[0].cnt,H="";
  rows.forEach(function(r,i){
    H+="<div class=\"dlab-inst-row\" data-n=\""+r.n+"\" onclick=\"dlabInstClick(this)\" style=\"border-left-color:"+c.color+"40\">";
    H+="<span class=\"dlab-inst-rank\">"+(i+1)+"</span>";
    H+="<span class=\"dlab-inst-name\">"+r.n+"</span>";
    H+="<div class=\"dlab-inst-bar\"><div class=\"dlab-inst-bar-fill\" style=\"width:"+Math.round(r.cnt/mx*100)+"%;background:"+c.color+"\"></div></div>";
    H+="<span class=\"dlab-inst-cnt\" style=\"color:"+c.color+"\">"+r.cnt+"人</span></div>";
  });
  return "<div class=\"dlab-sec-hd\"><h3>🏛 机构排行</h3><span class=\"dlab-sec-badge\" style=\"color:"+c.color+";border-color:"+c.color+"40\">"+rows.length+"所</span></div>"
    +"<div class=\"dlab-inst-list\">"+H+"</div>";
}
function dAll(Ss,c){
  var list=Ss.slice().sort(function(a,b){return (b.hats.length+b.hon.length)-(a.hats.length+a.hon.length);});
  var G="";list.forEach(function(s){G+=dCard(s,c.color);});
  return "<div class=\"dlab-sec-hd\"><h3>👥 全部学者</h3><span class=\"dlab-sec-badge\" style=\"color:"+c.color+";border-color:"+c.color+"40\">"+list.length+"位</span></div>"
    +"<div class=\"dlab-scholar-grid\">"+G+"</div>";
}
function dCard(s,ac){
  var tags="";
  s.hats.slice(0,2).forEach(function(h){tags+="<span class=\"dlab-tag dlab-tag-hat\">"+h.slice(0,10)+"</span>";});
  s.hon.slice(0,1).forEach(function(h){tags+="<span class=\"dlab-tag dlab-tag-hon\">"+h.slice(0,12)+"</span>";});
  return "<div class=\"dlab-scard\" style=\"border-left-color:"+ac+"40\" onclick=\"openMod(S.find(function(x){return x.id==="+s.id+";}))\""+">"
    +"<div class=\"dlab-scard-top\">"
    +"<div class=\"sci-avatar\" style=\"background:"+ac+"18;color:"+ac+"\">"+s.i+"</div>"
    +"<div class=\"dlab-scard-meta\"><div class=\"dlab-scard-name\">"+s.n+"</div>"
    +"<div class=\"dlab-scard-inst\">🏛 "+s.s+"</div></div></div>"
    +"<div class=\"dlab-scard-r\">📌 "+s.r+"</div>"
    +"<div class=\"dlab-scard-tags\">"+tags+"</div></div>";
}

