/* ── 导航点击下拉 ── */
function navToggle(id){
  var panel=document.getElementById('ndp-'+id);
  var trigger=panel&&panel.previousElementSibling;
  var ov=document.getElementById('navOverlay');
  var alreadyOpen=panel&&panel.classList.contains('open');
  navCloseAll();
  if(!alreadyOpen&&panel){
    panel.classList.add('open');
    if(trigger)trigger.classList.add('open');
    if(ov)ov.classList.add('show');
  }
}
function navCloseAll(){
  document.querySelectorAll('.ndd-p').forEach(function(p){p.classList.remove('open');});
  document.querySelectorAll('.ndd-t').forEach(function(t){t.classList.remove('open');});
  var ov=document.getElementById('navOverlay');
  if(ov)ov.classList.remove('show');
}
