/* ══ 多选对比 ══ */
var compareList=[];
function toggleCompare(id,e){
  if(e)e.stopPropagation();
  var idx=compareList.indexOf(id);
  if(idx>=0)compareList.splice(idx,1);
  else if(compareList.length<5)compareList.push(id);
  updateCompareBar();
  document.querySelectorAll('.cmp-btn').forEach(function(btn){
    var bid=parseInt(btn.dataset.sid);
    var active=compareList.includes(bid);
    btn.textContent=active?'\u2713 \u5df2\u9009':'\u2295 \u5bf9\u6bd4';
    btn.style.color=active?'#10b981':'';btn.style.borderColor=active?'rgba(16,185,129,.4)':'';btn.style.background=active?'rgba(16,185,129,.08)':'';
  });
}
function updateCompareBar(){
  var bar=document.getElementById('compareBar');if(!bar)return;
  bar.style.display=compareList.length>0?'flex':'none';
  var cnt=document.getElementById('compareCnt');
  if(cnt)cnt.innerHTML='<b style="color:#2E9A89">'+compareList.length+'</b>/5 \u4f4d\u5b66\u8005\u5df2\u9009';
}
function clearCompare(){
  compareList=[];updateCompareBar();
  document.querySelectorAll('.cmp-btn').forEach(function(b){b.textContent='\u2295 \u5bf9\u6bd4';b.style.color='';b.style.borderColor='';b.style.background='';});
}
function showCompareTable(){
  if(compareList.length<2){alert('\u8bf7\u81f3\u5c11\u9009\u62e92\u4f4d\u5b66\u8005');return;}
  var scholars=compareList.map(function(id){return S.find(function(s){return s.id===id;});}).filter(Boolean);
  var H='<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:.81rem;">';
  H+='<thead><tr><th style="padding:9px 12px;background:#0a1530;color:#8A94A8;text-align:left;border-bottom:2px solid #1e2d50;min-width:80px;">\u7ef4\u5ea6</th>';
  scholars.forEach(function(s){H+='<th style="padding:9px 12px;background:#0a1530;color:#e2e8f0;text-align:left;border-bottom:2px solid #1e2d50;min-width:160px;"><div style="font-weight:700;">'+s.n+'</div><div style="font-size:.7rem;color:#64748b;">'+s.s+'</div></th>';});
  H+='</tr></thead><tbody>';
  var dims=[{l:'\u673a\u6784',f:function(s){return s.institution;}},{l:'\u804c\u79f0',f:function(s){return s.title||'\u2014';}},
    {l:'\u4eba\u624d\u8ba1\u5212',f:function(s){return s.hats.length?s.hats.map(function(h){return '<span style="padding:1px 5px;border-radius:3px;background:rgba(200,162,75,.1);color:#f59e0b;font-size:.7rem;margin:1px;display:inline-block;">'+h+'</span>';}).join(''):'\u2014';}},
    {l:'\u5b66\u79d1',f:function(s){return s.dL||'\u2014';}},{l:'\u7814\u7a76\u9886\u57df',f:function(s){return s.r||'\u2014';}}
  ];
  dims.forEach(function(row,ri){
    var bg=ri%2===0?'rgba(255,255,255,.02)':'transparent';
    H+='<tr><td style="padding:9px 12px;background:'+bg+';color:#8A94A8;font-weight:600;font-size:.74rem;border-bottom:1px solid rgba(255,255,255,.05);">'+row.l+'</td>';
    scholars.forEach(function(s){H+='<td style="padding:9px 12px;background:'+bg+';color:#e2e8f0;border-bottom:1px solid rgba(255,255,255,.05);">'+row.f(s)+'</td>';});
    H+='</tr>';
  });
  H+='</tbody></table></div>';
  H+='<div style="display:flex;gap:8px;justify-content:flex-end;padding-top:12px;">';
  H+='<button onclick="exportCompareCSV()" style="padding:6px 14px;border-radius:7px;border:1px solid rgba(16,185,129,.3);color:#10b981;background:rgba(16,185,129,.07);cursor:pointer;font-family:inherit;font-size:.8rem;">\uD83D\uDCE5 \u5bfc\u51fa\u5bf9\u6bd4\u8868</button>';
  H+='<button onclick="clearCompare();closeMod();" style="padding:6px 14px;border-radius:7px;border:1px solid rgba(255,255,255,.1);color:#8A94A8;cursor:pointer;font-family:inherit;font-size:.8rem;">\u5173\u95ed</button>';
  H+='</div>';
  var mtp=document.getElementById('mtp');if(mtp)mtp.innerHTML='<div style="font-size:1rem;font-weight:700;color:#f0f4ff;padding-bottom:12px;margin-bottom:12px;border-bottom:1px solid rgba(255,255,255,.08);">\uD83D\uDCCA \u5b66\u8005\u5bf9\u6bd4\uff08'+scholars.length+'\u4eba\uff09</div>';
  var mb=document.getElementById('mb');if(mb)mb.innerHTML=H;
  var ov=document.getElementById('ov');if(ov)ov.style.display='flex';
}
function exportCompareCSV(){
  var scholars=compareList.map(function(id){return S.find(function(s){return s.id===id;});}).filter(Boolean);
  var bom=String.fromCharCode(0xFEFF);
  var csv=bom+'\u59d3\u540d,\u673a\u6784,\u804c\u79f0,\u5b66\u79d1\u65b9\u5411,\u4eba\u624d\u8ba1\u5212\n';
  csv+=scholars.map(function(s){return [s.n,s.institution,s.title||'',s.dL||'",'+s.hats.join(';')+'"'].join(',');}).join('\n');
  var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='\u5b66\u8005\u5bf9\u6bd4.csv';document.body.appendChild(a);a.click();document.body.removeChild(a);
}

/* ══ 右键菜单 ══ */
var ctxMenu=null;
function showCtxMenu(e,sid){
  e.preventDefault();
  if(ctxMenu)ctxMenu.remove();
  var s=S.find(function(x){return x.id===sid;});if(!s)return;
  var x=Math.min(e.clientX,window.innerWidth-180);var y=Math.min(e.clientY,window.innerHeight-170);
  ctxMenu=document.createElement('div');
  ctxMenu.className='ctx-menu';
  ctxMenu.style.cssText='position:fixed;left:'+x+'px;top:'+y+'px;z-index:9000;background:#0f1a35;border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:6px;min-width:158px;box-shadow:0 12px 40px rgba(0,0,0,.5);';
  var inCmp=compareList.includes(sid);
  var items=[
    ['\uD83D\uDC64','\u67e5\u770b\u8be6\u60c5',function(){openMod(s);}],
    [inCmp?'\u2713':'\u2295',inCmp?'\u79fb\u51fa\u5bf9\u6bd4':'\u52a0\u5165\u5bf9\u6bd4',function(){toggleCompare(sid,null);}],
    ['\uD83D\uDCCB','\u590d\u5236\u540d\u79f0+\u673a\u6784',function(){if(navigator.clipboard)navigator.clipboard.writeText(s.n+' '+s.institution).then(function(){showToast('\u5df2\u590d\u5236');});}],
    ['\uD83C\uDF10','\u6253\u5f00\u5b98\u65b9\u4e3b\u9875',function(){window.open(s.url,'_blank');}],
  ];
  items.forEach(function(item){
    var div=document.createElement('div');div.className='ctx-item';
    div.innerHTML='<span>'+item[0]+'</span><span>'+item[1]+'</span>';
    div.addEventListener('click',function(){item[2]();if(ctxMenu){ctxMenu.remove();ctxMenu=null;}});
    ctxMenu.appendChild(div);
  });
  document.body.appendChild(ctxMenu);
  setTimeout(function(){document.addEventListener('click',function rmCtx(){if(ctxMenu){ctxMenu.remove();ctxMenu=null;}document.removeEventListener('click',rmCtx);},{once:true});},50);
}
function showToast(msg,type){
  var cc={success:['rgba(16,185,129,.3)','#10b981'],error:['rgba(244,63,94,.3)','#f43f5e']};
  var c=cc[type]||['rgba(46,154,137,.3)','#2E9A89'];
  var t=document.createElement('div');
  t.style.cssText='position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:rgba(10,20,48,.96);border:1px solid '+c[0]+';color:'+c[1]+';padding:8px 18px;border-radius:20px;font-size:.8rem;z-index:9999;pointer-events:none;box-shadow:0 8px 24px rgba(0,0,0,.3);';
  t.textContent=msg;document.body.appendChild(t);setTimeout(function(){t.remove();},2200);
}

