/* ══ 导出CSV ══ */
function exportCSV(){
  var rows=S.filter(function(s){
    if(q&&!(s.n+s.institution+s.r+s.dL).toLowerCase().includes(q.toLowerCase()))return false;
    if(inst&&s.institution!==inst)return false;
    if(cat&&s.disc!==cat)return false;
    if(gender&&s.g!==gender)return false;
    return true;
  });
  var bom=String.fromCharCode(0xFEFF);
  var hdr='\u59d3\u540d,\u673a\u6784,\u9662\u7cfb,\u804c\u79f0,\u5b66\u79d1\u65b9\u5411,\u7814\u7a76\u9886\u57df,\u4eba\u624d\u8ba1\u5212';
  var csv=bom+hdr+'\n';
  csv+=rows.map(function(s){return [s.n,s.institution,s.dept||'',s.title||'',s.dL||'','"'+(s.r||'').replace(/"/g,'""')+'"','"'+s.hats.join(';')+'"'].join(',');}).join('\n');
  var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='\u4f53\u80b2\u5b66\u4eba.csv';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  showToast('\u5df2\u5bfc\u51fa '+rows.length+' \u6761');
}

