function dpBuildPhd(){
  if(!PHD_INSTS||!PHD_INSTS.length)return '<div style="padding:40px;text-align:center;color:#64748b;">\u6570\u636e\u52a0\u8f7d\u4e2d</div>';
  var iCnt={};S.forEach(function(s){iCnt[s.institution]=(iCnt[s.institution]||0)+1;});
  var ro={'A+':1,'A':2,'A-':3,'B+':4,'B':5,'B-':6};
  var list=PHD_INSTS.slice().sort(function(a,b){return (ro[a.rank4]||99)-(ro[b.rank4]||99);});
  var H='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:10px;">';
  list.forEach(function(p){
    var isDual=p.phdAcad&&p.phdProf;var lc=isDual?'#3b82f6':p.phdProf?'#f59e0b':'#818cf8';
    var sc_cnt=iCnt[p.n]||0;
    H+='<div style="background:#ffffff05;border:1px solid #ffffff0e;border-radius:10px;padding:13px;border-left:3px solid '+lc+';">';
    H+='<div style="display:flex;align-items:flex-start;gap:8px;margin-bottom:7px;">';
    H+='<div style="font-weight:600;font-size:.88rem;flex:1;">';
    H+='<a href="'+(p.szdwUrl||p.url||'#')+'" target="_blank" rel="noopener" style="color:#e2e8f0;text-decoration:none;transition:color .15s;" onmouseover="this.style.color=\'#2E9A89\'" onmouseout="this.style.color=\'#e2e8f0\'">'+p.n+'</a>';
    H+='</div>';
    if(p.rank4)H+='<span style="padding:2px 6px;border-radius:4px;font-size:.63rem;font-weight:700;background:rgba(234,179,8,.1);color:#eab308;border:1px solid rgba(234,179,8,.25);">'+p.rank4+'</span>';
    H+='</div><div style="font-size:.67rem;color:#8A94A8;margin-bottom:6px;">'+p.note+'</div>';
    H+='<div style="display:flex;gap:5px;flex-wrap:wrap;">';
    if(isDual)H+='<span style="padding:2px 6px;border-radius:3px;font-size:.63rem;background:rgba(16,185,129,.1);color:#10b981;border:1px solid rgba(16,185,129,.25);">\u2295\u53cc\u6388\u6743</span>';
    if(p.phdAcad)H+='<span style="font-size:.63rem;color:#64748b;">\u5b66\u535a'+p.phdAcad+'</span>';
    if(p.phdProf)H+='<span style="font-size:.63rem;color:#64748b;">\u4e13\u535a'+p.phdProf+'</span>';
    H+='</div>';
    H+='<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:7px;align-items:center;">';
    if(p.szdwUrl)H+='<a href="'+p.szdwUrl+'" target="_blank" rel="noopener" style="font-size:.68rem;color:#10b981;text-decoration:none;border:1px solid rgba(16,185,129,.28);border-radius:5px;padding:2px 7px;">体育学院 ↗</a>';
    if(p.url)H+='<a href="'+p.url+'" target="_blank" rel="noopener" style="font-size:.68rem;color:#3E82B0;text-decoration:none;border:1px solid rgba(56,189,248,.2);border-radius:5px;padding:2px 7px;">学校官网</a>';
    if(sc_cnt>0)H+='<span data-n="'+p.n+'" onclick="filterToInst(this.dataset.n)" style="font-size:.68rem;color:#2E9A89;cursor:pointer;border:1px solid rgba(46,154,137,.18);border-radius:5px;padding:2px 7px;">\uD83D\uDCCB '+sc_cnt+'\u4f4d \u2192</span>';
    H+='</div>';
    H+='</div>';
  });
  H+='</div>';return H;
}
function dpBuildTimeline(){
  if(!PHD_INSTS||!PHD_INSTS.length)return '<div style="padding:40px;text-align:center;color:#64748b;">\u6570\u636e\u52a0\u8f7d\u4e2d</div>';
  var byYear={};
  PHD_INSTS.forEach(function(p){var yr=p.phdAcad?p.phdAcad:(p.phdProf||0);if(!byYear[yr])byYear[yr]=[];byYear[yr].push(p);});
  var years=Object.keys(byYear).map(Number).sort(function(a,b){return a-b;});
  var H='<div style="display:flex;flex-direction:column;">';
  years.forEach(function(yr){
    var items=byYear[yr];
    H+='<div style="display:flex;"><div style="width:76px;flex-shrink:0;font-family:DM Mono,monospace;font-size:.76rem;color:#818cf8;font-weight:700;padding:10px 10px 10px 0;text-align:right;border-right:2px solid rgba(99,102,241,.3);">'+yr+'</div>';
    H+='<div style="padding:8px 0 8px 14px;display:flex;flex-wrap:wrap;gap:5px;flex:1;">';
    items.forEach(function(p){
      var isDual=p.phdAcad&&p.phdProf;
      H+='<span data-n="'+p.n+'" onclick="filterToInst(this.dataset.n)" style="padding:3px 9px;border-radius:5px;font-size:.72rem;cursor:pointer;'+(isDual?'background:rgba(16,185,129,.1);border:1px solid rgba(16,185,129,.2);color:#6ee7b7;':'background:rgba(99,102,241,.1);border:1px solid rgba(99,102,241,.2);color:#c7d2fe;')+'">'+p.n+(p.rank4?'<span style="font-size:.58rem;margin-left:2px;opacity:.65">'+p.rank4+'</span>':'')+'</span>';
    });
    H+='</div></div>';
  });
  H+='</div>';return H;
}


/* ── 地图模式 ── */
var _mapOpen=false;
function toggleInstMap(){
  _mapOpen=!_mapOpen;
  var c=document.getElementById('instMapContainer');
  var b=document.getElementById('mapViewBtn');
  if(c){
    c.style.display=_mapOpen?'block':'none';
    if(_mapOpen){
      initMapRegionList();
      // 地图出现动画
      c.style.animation='none';c.offsetHeight;c.style.animation='vIn .3s ease';
    }
  }
  if(b){
    b.style.background=_mapOpen?'rgba(46,154,137,.18)':'rgba(46,154,137,.08)';
    b.innerHTML=_mapOpen?'✕ 关闭地图':'🗺 地图模式';
  }
}
function initMapRegionList(){
  var el=document.getElementById('mapRegionList');
  if(!el||el.dataset.init) return;
  el.dataset.init='1';
  var REGS=[
    {k:'华北',icon:'🏙',c:'#4A8EE0',cnt:23,provs:'北京·天津·河北·山西·内蒙'},
    {k:'东北',icon:'❄',c:'#5EC8E5',cnt:12,provs:'辽宁·吉林·黑龙江'},
    {k:'华东',icon:'🌊',c:'#3DBD8C',cnt:34,provs:'沪·苏·浙·皖·闽·赣·鲁'},
    {k:'华中',icon:'🌸',c:'#E96FA0',cnt:17,provs:'河南·湖北·湖南'},
    {k:'华南',icon:'☀',c:'#F4923C',cnt:7, provs:'广东·广西·海南'},
    {k:'西南',icon:'🏔',c:'#4DA85E',cnt:8, provs:'渝·川·黔·滇·藏'},
    {k:'西北',icon:'🏜',c:'#9B7FD4',cnt:8, provs:'陕·甘·青·宁·新'},
  ];
  el.innerHTML=REGS.map(function(r){
    return '<div onclick="mapClickRegion(\''+r.k+'\')" style="display:grid;grid-template-columns:26px 1fr auto;align-items:center;gap:7px;padding:7px 9px;border-radius:8px;cursor:pointer;border:1px solid transparent;margin-bottom:3px;transition:all .12s;" class="map-list-row" data-region="'+r.k+'">'
      +'<div style="width:26px;height:26px;border-radius:7px;background:'+r.c+'22;display:flex;align-items:center;justify-content:center;font-size:.82rem;">'+r.icon+'</div>'
      +'<div><div style="font-size:.79rem;font-weight:700;color:'+r.c+';">'+r.k+'</div>'
      +'<div style="font-size:.6rem;color:#64748b;margin-top:1px;">'+r.provs+'</div></div>'
      +'<div style="font-family:DM Mono,monospace;font-size:.95rem;font-weight:700;color:'+r.c+';">'+r.cnt+'<span style="font-size:.6rem;opacity:.55;font-weight:400;">所</span></div>'
      +'</div>';
  }).join('');
}
function mapClickRegion(region){
  // 高亮地图区域
  document.querySelectorAll('.map-region').forEach(function(g){g.classList.remove('active-reg');});
  if(region!=='all'){var activeG=document.getElementById('map-'+region);if(activeG)activeG.classList.add('active-reg');}
  document.querySelectorAll('.map-region').forEach(function(g){
    g.style.opacity=region==='all'?'':( g.id==='map-'+region?'1':'0.35');
  });
  // 高亮列表行
  document.querySelectorAll('.map-list-row').forEach(function(row){
    var isActive=region==='all'||row.dataset.region===region;
    row.style.background=isActive?'rgba(255,255,255,.06)':'transparent';
    row.style.borderColor=isActive?'rgba(255,255,255,.1)':'transparent';
  });
  // 同步地区Tab
  var regionRow=document.getElementById('instRegionTabs');
  if(regionRow){
    regionRow.querySelectorAll('.l1-tab').forEach(function(b){
      b.classList.remove('on');
      if(b.dataset.region===region||(region==='all'&&b.dataset.region==='all')) b.classList.add('on');
    });
    // 触发筛选
    var target=regionRow.querySelector('[data-region="'+region+'"]');
    if(target) target.click();
  }
}


