var mcActiveTag='all';
var mcActiveCode=null;

function renderMajorCat(){
  // 统计KPI
  var totalScholars=new Set();
  var totalInsts=new Set();
  MAJORS_DATA.forEach(function(m){
    var disc=m.disc;
    S.filter(function(s){return s.disc===disc;}).forEach(function(s){
      totalScholars.add(s.id);
      totalInsts.add(s.institution);
    });
  });
  var kpiS=document.getElementById('mcKpiScholar');
  var kpiI=document.getElementById('mcKpiInst');
  if(kpiS) kpiS.textContent=totalScholars.size+'人';
  if(kpiI) kpiI.textContent=totalInsts.size+'所';
  mcRenderGrid(MAJORS_DATA);
}

function mcFilter(){
  var q=(document.getElementById('mcSearch')||{}).value||'';
  var filtered=MAJORS_DATA.filter(function(m){
    var matchQ=!q||m.code.includes(q)||m.name.includes(q)||m.desc.includes(q);
    var matchTag=mcActiveTag==='all'||m.tag===mcActiveTag||(mcActiveTag==='TK'&&m.tag==='TK');
    return matchQ&&matchTag;
  });
  mcRenderGrid(filtered);
}

function mcTagClick(btn,tag){
  mcActiveTag=tag;
  document.querySelectorAll('.mc-tag').forEach(function(b){b.classList.remove('on');});
  btn.classList.add('on');
  mcFilter();
}

function mcClose(){
  var d=document.getElementById('mcDetail');
  if(d)d.style.display='none';
  document.querySelectorAll('.mc-card').forEach(function(c){c.classList.remove('active');});
  mcActiveCode=null;
}
function mcJumpDisc(disc){
  go('scholars');
  setTimeout(function(){var el=document.getElementById('fcat');if(el){el.value=disc;cat=disc;renderSc();}},150);
}
function mcRenderGrid(list){
  var grid=document.getElementById('mcGrid');
  if(!grid) return;
  var detail=document.getElementById('mcDetail');
  if(detail) detail.style.display='none';
  mcActiveCode=null;
  document.querySelectorAll('.mc-card').forEach(function(c){c.classList.remove('active');});
  var H='';
  list.forEach(function(m){
    var scholars=S.filter(function(s){return s.disc===m.disc;});
    var instSet=new Set(scholars.map(function(s){return s.institution;}));
    var tagLabel='';
    if(m.tag){
      var tc=m.tag==='K'?'rgba(44,110,158,.15)':m.tag==='TK'?'rgba(200,162,75,.15)':'rgba(16,185,129,.15)';
      var tt=m.tag==='K'?'#60a5fa':m.tag==='TK'?'#f59e0b':'#34d399';
      tagLabel='<span class="mc-badge" style="background:'+tc+';color:'+tt+'">'+m.tag+'</span>';
    }
    H+='<div class="mc-card" data-code="'+m.code+'" onclick="mcClickCard(this)" style="border-top:3px solid '+m.color+';cursor:pointer;">';
    H+='<div class="mc-code">'+m.code+'</div>';
    H+='<div class="mc-name">'+m.icon+' '+m.name+tagLabel+'</div>';
    H+='<div style="font-size:.72rem;color:#64748b;line-height:1.55;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;">'+m.desc+'</div>';
    H+='<div class="mc-fields">';
    m.keyFields.forEach(function(f){H+='<span class="mc-field-chip">'+f+'</span>';});
    H+='</div>';
    H+='<div class="mc-stats"><div class="mc-stat">&#x1F3EB; <b>'+instSet.size+'</b>所</div><div class="mc-stat">&#x1F464; <b>'+scholars.length+'</b>位</div></div>';
    H+='<div style="margin-top:8px;font-size:.7rem;color:'+m.color+';opacity:.75;">点击展开详情 &#x2192;</div>';
    H+='</div>';
  });
  grid.innerHTML=H||'<div style="text-align:center;padding:40px;color:#64748b;">没有找到匹配专业</div>';
}
function mcClickCard(cardEl){
  var code=cardEl.dataset.code;
  if(!code) return;
  if(mcActiveCode===code){mcClose();return;}
  var major=MAJORS_DATA.find(function(m){return m.code===code;});
  if(!major) return;
  var scholars=S.filter(function(s){return s.disc===major.disc;});
  var instMap={};
  scholars.forEach(function(s){
    if(!instMap[s.institution])instMap[s.institution]=[];
    instMap[s.institution].push(s);
  });
  document.querySelectorAll('.mc-card').forEach(function(c){c.classList.remove('active');});
  cardEl.classList.add('active');
  mcActiveCode=code;
  mcBuildDetail(major,scholars,instMap);
}
function mcBuildDetail(major,scholars,instMap){
  var detail=document.getElementById('mcDetail');
  if(!detail) return;
  var instList=Object.keys(instMap);
  var instsSorted=Object.entries(instMap).sort(function(a,b){return b[1].length-a[1].length;});
  var sorted=scholars.slice().sort(function(a,b){return b.hats.length-a.hats.length;});
  var eliteCnt=sorted.filter(function(s){return s.hats&&s.hats.length;}).length;
  var deanCnt=sorted.filter(function(s){return s.role==='dean'||s.role==='vp';}).length;
  var H='';
  H+='<div class="mc-detail-hd">';
  H+='<div style="width:48px;height:48px;border-radius:12px;background:'+major.color+'18;border:1px solid '+major.color+'30;display:flex;align-items:center;justify-content:center;font-size:1.6rem;flex-shrink:0;">'+major.icon+'</div>';
  H+='<div style="flex:1;min-width:0;"><div style="font-family:Noto Serif SC,serif;font-size:1.05rem;font-weight:800;color:'+major.color+';">'+major.name;
  if(major.tag)H+='<span style="font-size:.7rem;margin-left:6px;padding:1px 6px;border-radius:3px;background:'+major.color+'18;color:'+major.color+'">'+major.tag+'</span>';
  H+='</div><div style="font-family:DM Mono,monospace;font-size:.72rem;color:#64748b;margin-top:2px;">'+major.code+'</div></div>';
  H+='<button onclick="mcClose()" style="padding:5px 12px;border-radius:7px;border:1px solid rgba(255,255,255,.1);background:transparent;color:#8A94A8;cursor:pointer;font-size:.76rem;flex-shrink:0;font-family:inherit;">&#x2715; 收起</button>';
  H+='</div>';
  H+='<div style="font-size:.78rem;color:#8A94A8;line-height:1.65;padding:10px 14px;background:rgba(255,255,255,.03);border-radius:8px;border-left:3px solid '+major.color+'40;margin-bottom:14px;">'+major.desc+'</div>';
  H+='<div style="margin-bottom:14px;"><div style="font-size:.68rem;font-weight:700;letter-spacing:.08em;color:#64748b;text-transform:uppercase;margin-bottom:6px;">核心知识领域</div><div style="display:flex;gap:6px;flex-wrap:wrap;">';
  major.keyFields.forEach(function(f){H+='<span style="padding:4px 11px;border-radius:5px;font-size:.73rem;background:'+major.color+'12;border:1px solid '+major.color+'25;color:'+major.color+';">'+f+'</span>';});
  H+='</div></div>';
  H+='<div style="display:flex;gap:16px;margin-bottom:16px;padding:10px 16px;background:rgba(255,255,255,.03);border-radius:8px;border:1px solid rgba(255,255,255,.06);">';
  var kpis=[{v:instList.length,l:'开设院校',c:major.color},{v:scholars.length,l:'关联学者',c:'#60a5fa'},{v:eliteCnt,l:'人才计划',c:'#f59e0b'},{v:deanCnt,l:'院长/校长',c:'#ec4899'}];
  kpis.forEach(function(kpi){
    H+='<div style="text-align:center;padding:0 8px;"><div style="font-family:DM Mono,monospace;font-size:1.4rem;font-weight:700;color:'+kpi.c+';">'+kpi.v+'</div><div style="font-size:.62rem;color:#64748b;margin-top:1px;">'+kpi.l+'</div></div>';
  });
  H+='</div>';
  H+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">';
  H+='<div><div style="font-size:.72rem;font-weight:700;color:#8A94A8;letter-spacing:.06em;text-transform:uppercase;margin-bottom:8px;">&#x1F3EB; 开设院校（'+instList.length+'所）</div>';
  H+='<div style="display:flex;flex-wrap:wrap;gap:5px;max-height:230px;overflow-y:auto;padding-right:4px;">';
  instsSorted.forEach(function(e){
    H+='<span class="mc-inst-chip" data-inst="'+e[0]+'" onclick="filterToInst(this.dataset.inst)">'+e[0]+'<span style="font-family:DM Mono,monospace;font-size:.58rem;opacity:.6;margin-left:3px;">'+e[1].length+'人</span></span>';
  });
  H+='</div>';
  H+='<div style="margin-top:8px;"><span onclick="mcJumpDisc(\''+major.disc+'\')" style="font-size:.71rem;color:#2E9A89;cursor:pointer;">&#x2192; 筛选此学科全部学者</span></div></div>';
  H+='<div><div style="font-size:.72rem;font-weight:700;color:#8A94A8;letter-spacing:.06em;text-transform:uppercase;margin-bottom:8px;">&#x1F464; 关联学者（'+scholars.length+'位）</div>';
  H+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px;max-height:230px;overflow-y:auto;padding-right:4px;">';
  sorted.slice(0,24).forEach(function(s){
    H+='<div class="mc-scholar-chip" onclick="var f=S.find(function(x){return x.id==='+s.id+';});if(f)openMod(f);">';
    H+='<div style="display:flex;align-items:center;gap:5px;">';
    H+='<div style="width:22px;height:22px;border-radius:5px;background:'+s.c+'22;color:'+s.c+';display:flex;align-items:center;justify-content:center;font-size:.72rem;font-weight:700;flex-shrink:0;">'+s.i+'</div>';
    H+='<div style="min-width:0;"><div style="font-size:.77rem;font-weight:600;color:#e2e8f0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+s.n+'</div>';
    H+='<div style="font-size:.6rem;color:#64748b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+s.s+'</div></div></div>';
    if(s.hats&&s.hats.length)H+='<div style="font-size:.59rem;color:#f59e0b;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">&#x2B50; '+s.hats[0]+'</div>';
    H+='</div>';
  });
  H+='</div>';
  if(scholars.length>24)H+='<div style="margin-top:6px;font-size:.7rem;color:#64748b;">还有'+(scholars.length-24)+'位 <span onclick="mcJumpDisc(\''+major.disc+'\')" style="color:#2E9A89;cursor:pointer;">查看全部 &#x2192;</span></div>';
  H+='</div></div>';
  detail.innerHTML=H;
  detail.style.display='block';
  setTimeout(function(){detail.scrollIntoView({behavior:'smooth',block:'nearest'});},80);
}


