function toggleMobileMenu(){
  var nm = document.querySelector('.nm');
  var btn = document.getElementById('mobileMenuBtn');
  if(!nm || !btn) return;
  var isOpen = nm.classList.contains('mobile-open');
  nm.classList.toggle('mobile-open');
  // 汉堡图标变 X
  var spans = btn.querySelectorAll('span');
  if(!isOpen){
    if(spans[0]) spans[0].style.transform = 'rotate(45deg) translate(4px, 4px)';
    if(spans[1]) spans[1].style.opacity = '0';
    if(spans[2]) spans[2].style.transform = 'rotate(-45deg) translate(4px, -4px)';
  } else {
    spans.forEach(function(s){ s.style.transform=''; s.style.opacity=''; });
  }
}

