/* ── 8.1 全站统计口径自动同步 ── */
function syncLiveMetrics(){
  if(typeof S === 'undefined' || !Array.isArray(S)) return;
  var total = S.length;
  var instN = new Set(S.map(function(s){return s.institution;}).filter(Boolean)).size;
  var today = new Date();
  var y = today.getFullYear(), m = today.getMonth()+1, d = today.getDate();
  var cnDate = y+'年'+m+'月'+d+'日';
  var isoDate = y+'-'+String(m).padStart(2,'0')+'-'+String(d).padStart(2,'0');
  var fmt = function(n){return Number(n || 0).toLocaleString('zh-CN');};

  var brand = document.getElementById('brandStats');
  if(brand) brand.textContent = 'CSSD v4.6-87 · '+fmt(total)+'人 · '+fmt(instN)+'机构';

  var hero = document.getElementById('heroDesc');
  if(hero){
    hero.innerHTML = '面向体育学学科建设、师资队伍分析、院校对标与人才评价的综合知识库。当前收录<b>'+fmt(total)+'位</b>体育学者，覆盖<b>'+fmt(instN)+'所</b>高校、医院与科研机构，支持按学科方向、院校类型、人才项目、学位授权点和研究主题进行交叉检索与分析。';
  }

  var live = document.getElementById('heroLiveDate');
  if(live) live.textContent = cnDate;

  var homeDate = document.getElementById('homeUpdateDate');
  if(homeDate) homeDate.textContent = isoDate;

  var homeTotal = document.getElementById('homeTotalCount');
  if(homeTotal) homeTotal.textContent = fmt(total);

  var homeInst = document.getElementById('homeInstCount');
  if(homeInst) homeInst.textContent = fmt(instN);

  document.querySelectorAll('.pv-date').forEach(function(el){
    el.innerHTML = '最后更新：'+isoDate+' &nbsp;·&nbsp; CSSD v4.6-87';
  });
}
syncLiveMetrics();
document.addEventListener('DOMContentLoaded', syncLiveMetrics);
window.addEventListener('load', syncLiveMetrics);

