/* ── 10. KPI 数字动画（首次进入） ── */
function animateKPINumbers(){
  var knEls = document.querySelectorAll('.kn');
  knEls.forEach(function(el){
    var text = el.textContent.replace(/[^\d]/g,'');
    if(!text) return;
    var target = parseInt(text, 10);
    if(isNaN(target) || target <= 0) return;
    var duration = 900;
    var start = performance.now();
    var orig = el.textContent;
    function step(now){
      var elapsed = now - start;
      var progress = Math.min(elapsed / duration, 1);
      var ease = 1 - Math.pow(1 - progress, 3);
      var cur = Math.round(ease * target);
      el.textContent = orig.replace(text, cur.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','));
      if(progress < 1) requestAnimationFrame(step);
      else el.textContent = orig.replace(text, target.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','));
    }
    requestAnimationFrame(step);
  });
}
// 延迟触发，等KPI渲染完成
setTimeout(animateKPINumbers, 600);

