/* ── 状态变量 ── */
var jnlCurrentTab = 'cn';
var jnlCurrentView = 'card';
var jnlCnActiveFilter = 'all';
var jnlIntActiveFilter = 'all';
var jnlInitialized = false;

/* ── 主渲染函数 ── */
function renderJournals() {
  if (jnlInitialized) return;
  jnlInitialized = true;
  renderJnlCn(JNL_CN);
  renderJnlInt(JNL_INT);
}

/* ── Tab 切换 ── */
function jnlSwitchTab(tab) {
  jnlCurrentTab = tab;
  var _vt=document.getElementById('jnlViewToggle');
  if(_vt)_vt.style.display=(tab==='cnki')?'none':'';
  document.querySelectorAll('.jnl-tab').forEach(function(b) {
    b.classList.toggle('on', b.id === 'jnl-tab-' + tab);
  });
  document.querySelectorAll('.jnl-panel').forEach(function(p) {
    p.classList.toggle('on', p.id === 'jnl-panel-' + tab);
  });
}

/* ── 视图切换 ── */
function jnlSwitchView(v) {
  jnlCurrentView = v;
  document.querySelectorAll('.jnl-view-btn').forEach(function(b) {
    b.classList.toggle('on', b.dataset.v === v);
  });
  if (jnlCurrentTab === 'cn') renderJnlCn(jnlGetCnFiltered());
  else renderJnlInt(jnlGetIntFiltered());
}

/* ── 国内期刊筛选 ── */
function jnlGetCnFiltered() {
  var q = (document.getElementById('jnlCnSearch') || {}).value || '';
  q = q.toLowerCase();
  var f = jnlCnActiveFilter;
  return JNL_CN.filter(function(j) {
    var matchQ = !q || j.name.toLowerCase().includes(q) || j.en.toLowerCase().includes(q) ||
                 j.host.toLowerCase().includes(q) || j.field.toLowerCase().includes(q);
    var matchF = f === 'all' || j.tags.includes(f);
    return matchQ && matchF;
  });
}
function jnlCnFilter() { renderJnlCn(jnlGetCnFiltered()); }
function jnlCnChip(el, f) {
  jnlCnActiveFilter = f;
  document.querySelectorAll('#jnl-panel-cn .jnl-chip').forEach(function(b) { b.classList.remove('on'); });
  el.classList.add('on');
  renderJnlCn(jnlGetCnFiltered());
}

/* ── 国际期刊筛选 ── */
function jnlGetIntFiltered() {
  var q = (document.getElementById('jnlIntSearch') || {}).value || '';
  q = q.toLowerCase();
  var f = jnlIntActiveFilter;
  return JNL_INT.filter(function(j) {
    var matchQ = !q || j.name.toLowerCase().includes(q) || j.abbr.toLowerCase().includes(q) ||
                 j.publisher.toLowerCase().includes(q) || j.scope.toLowerCase().includes(q) ||
                 j.tags.some(function(t) { return t.includes(q); });
    var matchF = f === 'all' ||
      (f === 'q1' && j.jcrQ === 'Q1') ||
      (f === 'q2' && j.jcrQ === 'Q2') ||
      (f === 'casq1' && j.casQ === 'Q1') ||
      (f === 'ssci' && j.type.includes('ssci')) ||
      (f === 'sci' && j.type.includes('sci'));
    return matchQ && matchF;
  });
}
function jnlIntFilter() { renderJnlInt(jnlGetIntFiltered()); }
function jnlIntChip(el, f) {
  jnlIntActiveFilter = f;
  document.querySelectorAll('#jnl-panel-int .jnl-chip').forEach(function(b) { b.classList.remove('on'); });
  el.classList.add('on');
  renderJnlInt(jnlGetIntFiltered());
}

/* ── 渲染国内期刊 ── */
function renderJnlCn(list) {
  var info = document.getElementById('jnlCnInfo');
  if (info) info.innerHTML = '共 <b>' + list.length + '</b> 种期刊';
  var wrap = document.getElementById('jnlCnCards');
  if (!wrap) return;
  if (!list.length) {
    wrap.innerHTML = '<div class="jnl-empty"><div class="jnl-empty-ico">📭</div>未找到匹配的期刊，请调整筛选条件</div>';
    return;
  }

  if (jnlCurrentView === 'table') {
    wrap.innerHTML = '<div class="jnl-table-wrap">' +
      '<table class="jnl-table"><thead><tr>' +
      '<th>序号</th><th>期刊名称</th><th>英文名</th><th>主办单位</th><th>频次</th><th>收录</th><th>研究领域</th><th>官网</th>' +
      '</tr></thead><tbody>' +
      list.map(function(j, i) {
        return '<tr onclick="window.open(\'' + j.url + '\',\'_blank\')">' +
          '<td><span class="jnl-rank-num' + (i < 3 ? ' jnl-rank-top' : '') + '">' + (i + 1) + '</span></td>' +
          '<td><b style="font-family:\'Noto Serif SC\',serif;font-size:.88rem;">' + j.name + '</b></td>' +
          '<td style="font-size:.75rem;color:#8A94A8;font-family:\'DM Mono\',monospace;max-width:180px;">' + j.en + '</td>' +
          '<td style="font-size:.78rem;">' + j.host + '</td>' +
          '<td style="font-family:\'DM Mono\',monospace;font-size:.75rem;white-space:nowrap;">' + j.freq + '</td>' +
          '<td>' + j.tags.map(function(t) { return '<span class="jnl-badge ' + jnlCnBadgeClass(t) + '">' + jnlCnBadgeLabel(t) + '</span> '; }).join('') + '</td>' +
          '<td style="font-size:.78rem;color:#8A94A8;">' + j.field + '</td>' +
          '<td><a href="' + j.url + '" target="_blank" rel="noopener" class="jnl-visit-btn" onclick="event.stopPropagation()">访问 ↗</a></td>' +
          '</tr>';
      }).join('') +
      '</tbody></table></div>';
    return;
  }

  // 卡片视图
  // 分组：CSSCI+北大核心 / 仅北大核心 / 其他C刊
  var group1 = list.filter(function(j) { return j.tags.includes('cssci') && j.tags.includes('pku'); });
  var group2 = list.filter(function(j) { return j.tags.includes('cssci') && !j.tags.includes('pku'); });
  var groupE = list.filter(function(j) { return j.tags.includes('cssci_e'); });
  var group3 = list.filter(function(j) { return !j.tags.includes('cssci') && !j.tags.includes('cssci_e') && j.tags.includes('pku'); });
  var group4 = list.filter(function(j) { return !j.tags.includes('cssci') && !j.tags.includes('cssci_e') && !j.tags.includes('pku'); });
  var groups = [];
  if (group1.length) groups.push({ label:'CSSCI 来源期刊（2025-2026）· 北大核心双收录', badge:'jnl-badge-cssci', items: group1 });
  if (group2.length) groups.push({ label:'CSSCI 来源期刊（2025-2026）', badge:'jnl-badge-ssci', items: group2 });
  if (groupE.length) groups.push({ label:'CSSCI 扩展版来源期刊（2025-2026）', badge:'jnl-badge-cssciE', items: groupE });
  if (group3.length) groups.push({ label:'北大核心期刊', badge:'jnl-badge-pku', items: group3 });
  if (group4.length) groups.push({ label:'其他', badge:'jnl-badge-pku', items: group4 });

  wrap.innerHTML = groups.map(function(g) {
    return '<div class="jnl-sec-hd">' +
      '<h3>' + g.label + '</h3>' +
      '<span class="jnl-sec-cnt">' + g.items.length + ' 种</span>' +
      '</div>' +
      '<div class="jnl-cn-grid">' +
      g.items.map(function(j) { return renderJnlCnCard(j); }).join('') +
      '</div>';
  }).join('');
}

function jnlCnBadgeClass(t) {
  return t === 'cssci' ? 'jnl-badge-cssci' : t === 'cssci_e' ? 'jnl-badge-cssciE' : t === 'pku' ? 'jnl-badge-pku' :
         t === 'cscd' ? 'jnl-badge-cscd' : t === 'sci' ? 'jnl-badge-sci' : 'jnl-badge-ei';
}
function jnlCnBadgeLabel(t) {
  return t === 'cssci' ? 'CSSCI' : t === 'cssci_e' ? 'CSSCI扩展' : t === 'pku' ? '北大核心' :
         t === 'cscd' ? 'CSCD' : t === 'sci' ? 'SCI' : t.toUpperCase();
}

function renderJnlCnCard(j) {
  return '<div class="jnl-cn-card">' +
    '<div class="jnl-cn-top" style="background:' + j.color + '"></div>' +
    '<div class="jnl-cn-body">' +
      '<div class="jnl-cn-badges">' +
        j.tags.map(function(t) { return '<span class="jnl-badge ' + jnlCnBadgeClass(t) + '">' + jnlCnBadgeLabel(t) + '</span>'; }).join('') +
      '</div>' +
      '<div class="jnl-cn-title">' + j.name + '</div>' +
      '<div class="jnl-cn-en">' + j.en + '</div>' +
      '<div class="jnl-cn-meta">' +
        '<div class="jnl-cn-meta-item"><span class="jnl-cn-meta-lbl">主办单位</span><span class="jnl-cn-meta-val">' + j.host + '</span></div>' +
        '<div class="jnl-cn-meta-item"><span class="jnl-cn-meta-lbl">出版频次</span><span class="jnl-cn-meta-val">' + j.freq + '</span></div>' +
        '<div class="jnl-cn-meta-item"><span class="jnl-cn-meta-lbl">创刊年份</span><span class="jnl-cn-meta-val">' + j.founded + ' 年</span></div>' +
        '<div class="jnl-cn-meta-item"><span class="jnl-cn-meta-lbl">研究领域</span><span class="jnl-cn-meta-val">' + j.field + '</span></div>' +
      '</div>' +
      '<div class="jnl-cn-desc">' + j.desc + '</div>' +
    '</div>' +
    '<div class="jnl-cn-foot">' +
      '<span class="jnl-cn-issn">ISSN ' + j.issn + ' &nbsp;|&nbsp; CN ' + j.cn + '</span>' +
      '<a href="' + j.url + '" target="_blank" rel="noopener" class="jnl-visit-btn" onclick="event.stopPropagation()">访问官网 ↗</a>' +
    '</div>' +
  '</div>';
}

/* ── 渲染国际期刊 ── */
function renderJnlInt(list) {
  var info = document.getElementById('jnlIntInfo');
  if (info) info.innerHTML = '共 <b>' + list.length + '</b> 种期刊 · 按影响因子排序';
  var wrap = document.getElementById('jnlIntCards');
  if (!wrap) return;
  if (!list.length) {
    wrap.innerHTML = '<div class="jnl-empty"><div class="jnl-empty-ico">📭</div>未找到匹配的期刊，请调整筛选条件</div>';
    return;
  }

  if (jnlCurrentView === 'table') {
    wrap.innerHTML = '<div class="jnl-table-wrap">' +
      '<table class="jnl-table"><thead><tr>' +
      '<th>排名</th><th>期刊名称</th><th>简称</th><th>出版商</th><th>IF (2023)</th><th>JCR分区</th><th>中科院分区</th><th>类型</th><th>官网</th>' +
      '</tr></thead><tbody>' +
      list.map(function(j) {
        return '<tr onclick="window.open(\'' + j.url + '\',\'_blank\')">' +
          '<td><span class="jnl-rank-num' + (j.rank <= 3 ? ' jnl-rank-top' : '') + '">' + j.rank + '</span></td>' +
          '<td style="font-size:.85rem;font-weight:600;max-width:220px;line-height:1.35;">' + j.name + '</td>' +
          '<td style="font-family:\'DM Mono\',monospace;font-size:.75rem;color:#8A94A8;white-space:nowrap;">' + j.abbr + '</td>' +
          '<td style="font-size:.75rem;max-width:130px;">' + j.publisher + '</td>' +
          '<td><span class="' + j.ifColor + '" style="font-family:\'DM Mono\',monospace;font-weight:700;">' + j.if2023.toFixed(3) + '</span></td>' +
          '<td><span class="jnl-q-badge j' + j.jcrQ.toLowerCase() + '">' + j.jcrQ + '</span></td>' +
          '<td><span class="jnl-q-badge jcas' + j.casQ.replace('Q','') + '">' + j.casZone + '</span></td>' +
          '<td>' + j.type.map(function(t) { return '<span class="jnl-badge ' + (t==='ssci'?'jnl-badge-ssci':t==='sci'?'jnl-badge-sci':'jnl-badge-ei') + '">' + t.toUpperCase() + '</span> '; }).join('') + '</td>' +
          '<td><a href="' + j.url + '" target="_blank" rel="noopener" class="jnl-visit-btn" onclick="event.stopPropagation()">访问 ↗</a></td>' +
          '</tr>';
      }).join('') +
      '</tbody></table></div>';
    return;
  }

  // 卡片视图 — 按 JCR分区 分组（2025-2026 JCR 体育科学类 SCI）
  var casGroups = [
    { key:'Q1', label:'JCR 一区期刊（Q1 · 顶刊）', badge:'jcas1' },
    { key:'Q2', label:'JCR 二区期刊（Q2）', badge:'jcas2' },
    { key:'Q3', label:'JCR 三区期刊（Q3）', badge:'jcas3' },
    { key:'Q4', label:'JCR 四区期刊（Q4）', badge:'jcas4' }
  ];
  wrap.innerHTML = casGroups.map(function(g) {
    var items = list.filter(function(j) { return j.jcrQ === g.key; });
    if (!items.length) return '';
    return '<div class="jnl-sec-hd">' +
      '<h3>' + g.label + '</h3>' +
      '<span class="jnl-sec-badge ' + g.badge + '">' + g.key + '</span>' +
      '<span class="jnl-sec-cnt">' + items.length + ' 种</span>' +
      '</div>' +
      '<div class="jnl-int-grid">' +
      items.map(function(j) { return renderJnlIntCard(j); }).join('') +
      '</div>';
  }).join('');
}

function renderJnlIntCard(j) {
  var ifClass = j.if2023 >= 8 ? 'if-high' : j.if2023 >= 3 ? 'if-mid' : 'if-low';
  return '<div class="jnl-int-card">' +
    '<div class="jnl-int-top" style="background:' + j.topColor + '"></div>' +
    '<span class="jnl-int-rank-badge"># ' + j.rank + '</span>' +
    '<div class="jnl-int-body">' +
      '<div class="jnl-int-title">' + j.name + '</div>' +
      '<div class="jnl-int-pub">' + j.abbr + ' &nbsp;·&nbsp; ' + j.publisher + ' &nbsp;·&nbsp; ' + j.country + '</div>' +
      '<div class="jnl-metrics">' +
        '<div class="jnl-if"><div class="jnl-if-val ' + ifClass + '">' + j.if2023.toFixed(3) + '</div><div class="jnl-if-lbl">IF 2023</div></div>' +
        '<div class="jnl-if"><div class="jnl-if-val" style="color:#8A94A8;font-size:.85rem;">' + (j.if5yr ? j.if5yr.toFixed(1) : '—') + '</div><div class="jnl-if-lbl">IF 5年</div></div>' +
        '<span class="jnl-q-badge j' + j.jcrQ.toLowerCase() + '">JCR ' + j.jcrQ + '</span>' +
        '<span class="jnl-q-badge jcas' + j.casQ.replace('Q','') + '">中科院 ' + j.casQ + '</span>' +
        j.type.map(function(t) { return '<span class="jnl-badge ' + (t==='ssci'?'jnl-badge-ssci':t==='sci'?'jnl-badge-sci':'jnl-badge-ei') + '">' + t.toUpperCase() + '</span>'; }).join('') +
      '</div>' +
      '<div class="jnl-int-scope">' + j.scope + '</div>' +
      (j.note ? '<div style="font-size:.72rem;color:rgba(46,154,137,.65);line-height:1.55;margin-bottom:6px;font-style:italic;">💡 ' + j.note + '</div>' : '') +
      '<div class="jnl-int-tags">' + j.tags.map(function(t) { return '<span class="jnl-int-tag">' + t + '</span>'; }).join('') + '</div>' +
    '</div>' +
    '<div class="jnl-int-foot">' +
      '<span class="jnl-int-issn">ISSN ' + j.issn + (j.eissn ? ' &nbsp;/&nbsp; e-ISSN ' + j.eissn : '') + '</span>' +
      '<a href="' + j.url + '" target="_blank" rel="noopener" class="jnl-visit-btn" onclick="event.stopPropagation()">访问官网 ↗</a>' +
    '</div>' +
  '</div>';
}

