/* ── 状态 ── */
var fdrActiveEra = 'all';
var fdrInitialized = false;

/* ── 主渲染函数 ── */
function renderFounders() {
  if (fdrInitialized) { fdrRender(); return; }
  fdrInitialized = true;
  fdrRender();
}

function fdrFilter() {
  fdrRender();
}

function fdrJumpTo(id) {
  var el = document.getElementById(id);
  if (!el) return;
  el.scrollIntoView({ behavior:'smooth', block:'start' });
}

function fdrChipClick(el) {
  if (!el) return;
  document.querySelectorAll('.fdr-chip').forEach(function(b){ b.classList.remove('on'); });
  el.classList.add('on');
  fdrActiveEra = el.dataset.era || 'all';
  fdrRender();
}

function fdrGetFiltered() {
  var q = ((document.getElementById('fdrSearch') || {}).value || '').toLowerCase();
  return FOUNDERS.filter(function(f) {
    var matchEra = fdrActiveEra === 'all' ||
      f.era === fdrActiveEra ||
      (fdrActiveEra === 'tier1' && f.tier === 1);
    var matchQ = !q || f.name.includes(q) || f.pinyin.toLowerCase().includes(q) ||
      f.inst.includes(q) || f.role.includes(q) || f.field.includes(q) ||
      f.tags.some(function(t){ return t.includes(q); }) ||
      f.contribs.some(function(c){ return c.includes(q); });
    return matchEra && matchQ;
  });
}

var FDR_ERAS = [
  { key:'pioneer',  label:'先驱开创期', sub:'1880s — 1949', note:'现代体育教育肇始 · 奥运梦想点燃',
    badgeCls:'fdr-t1', color:'rgba(200,162,75,.22)', lineColor:'rgba(200,162,75,.3)' },
  { key:'founding', label:'建国奠基期', sub:'1949 — 1978', note:'新中国体育制度构建 · 举国体制确立',
    badgeCls:'fdr-t2', color:'rgba(168,85,247,.18)', lineColor:'rgba(168,85,247,.25)' },
  { key:'develop',  label:'学科建设期', sub:'1978 — 2000', note:'各学科分支体系建立 · 体育学术全面勃兴',
    badgeCls:'fdr-t3', color:'rgba(56,189,248,.18)', lineColor:'rgba(56,189,248,.25)' }
];

var FDR_TIER_LABELS = ['', '宗师级', '奠基人', '建设者', '开拓者'];

function fdrRender() {
  var list = fdrGetFiltered();
  var wrap = document.getElementById('fdrList');
  if (!wrap) return;

  if (!list.length) {
    wrap.innerHTML = '<div style="text-align:center;padding:80px 24px;color:rgba(245,234,208,.3);">' +
      '<div style="font-size:2.5rem;margin-bottom:12px;opacity:.5;">🏛️</div>' +
      '<div style="font-size:.9rem;">未找到匹配的先驱人物，请调整搜索条件</div></div>';
    return;
  }

  // 按时代分组（或不分组直接显示）
  var eraKeys = fdrActiveEra === 'all' || fdrActiveEra === 'tier1'
    ? ['pioneer','founding','develop']
    : [fdrActiveEra];

  var html = '';
  eraKeys.forEach(function(eraKey) {
    var era = FDR_ERAS.find(function(e){ return e.key === eraKey; });
    if (!era) return;
    var items = list.filter(function(f){ return f.era === eraKey; });
    if (!items.length) return;
    // tier1 first
    items.sort(function(a,b){ return a.tier - b.tier || FOUNDERS.indexOf(a) - FOUNDERS.indexOf(b); });

    html += '<div class="fdr-era-hd">' +
      '<div class="fdr-era-badge ' + era.badgeCls + '" style="border-color:' + era.lineColor + '">' +
        '<span style="font-size:.9rem">' + (eraKey==='pioneer'?'🏛️':eraKey==='founding'?'🏗️':'📐') + '</span>' +
        era.label + ' · ' + era.sub +
      '</div>' +
      '<div class="fdr-era-line" style="background:linear-gradient(90deg,' + era.lineColor + ',transparent)"></div>' +
      '<span class="fdr-era-cnt">' + items.length + ' 位先驱</span>' +
      '<span style="font-size:.65rem;color:rgba(122,132,148,.35);margin-left:6px;font-family:\'DM Mono\',monospace;">' + era.note + '</span>' +
    '</div>' +
    '<div class="fdr-grid">' +
    items.map(function(f){ return fdrCard(f); }).join('') +
    '</div>';
  });

  wrap.innerHTML = html || '<div style="text-align:center;padding:60px;color:rgba(245,234,208,.3);">暂无数据</div>';
}

function fdrCard(f) {
  var tierLabel = FDR_TIER_LABELS[f.tier] || '';
  var tierCls = 'fdr-t' + f.tier;
  return '<div class="fdr-card" data-tier="' + f.tier + '">' +
    '<div class="fdr-card-bar" style="background:' + f.bar + '"></div>' +
    '<div class="fdr-card-inner">' +
      '<div class="fdr-card-top">' +
        '<div class="fdr-avatar" style="background:' + f.avatarBg + '">' + f.avatar + '</div>' +
        '<div class="fdr-card-info">' +
          '<div class="fdr-name">' + f.name + '</div>' +
          '<div class="fdr-pinyin">' + f.pinyin + '</div>' +
          '<div class="fdr-years">⏳ ' + f.years + '</div>' +
          '<span class="fdr-tier-badge ' + tierCls + '">' + tierLabel + '</span>' +
        '</div>' +
      '</div>' +
      '<div class="fdr-inst">🏛️ ' + f.inst + '</div>' +
      '<div class="fdr-role">' + f.role + '</div>' +
      '<ul class="fdr-contrib-list">' +
        f.contribs.map(function(c){ return '<li class="fdr-contrib-item">' + c + '</li>'; }).join('') +
      '</ul>' +
      (f.quote ? '<blockquote class="fdr-quote">' + f.quote + '</blockquote>' : '') +
    '</div>' +
    '<div class="fdr-tags">' +
      f.tags.map(function(t){ return '<span class="fdr-tag">' + t + '</span>'; }).join('') +
    '</div>' +
  '</div>';
}

/* ── getInstUrl: 返回院校官网链接 ── */
function getInstUrl(name,s){
  if(s&&s.iu)return s.iu;
  if(typeof UNIV_CATALOG!=='undefined'){
    var u=UNIV_CATALOG.find(function(x){return x.n===name;});
    if(u&&u.iu)return u.iu;
    if(u&&u.url)return u.url;
  }
  if(typeof S!=='undefined'&&name){
    var found=S.find(function(x){return x.institution===name&&x.iu;});
    if(found)return found.iu;
  }
  return '#';
}
window.getInstUrl=getInstUrl;
/* ── getInstDept: 返回院校体育学院/体育部链接（仅非体育专业院校） ── */
function getInstDept(name){
  if(typeof UNIV_CATALOG==='undefined')return null;
  var u=UNIV_CATALOG.find(function(x){return x.n===name;});
  if(!u||!u.url||!u.dept)return null;
  if(u.dept==='全校'||u.grp==='spt')return null;        /* 体育专业院校无需单列 */
  if(u.iu&&u.url&&u.url.replace(/\/$/,'')===u.iu.replace(/\/$/,''))return null; /* 与主站相同则跳过 */
  return {url:u.url,dept:u.dept};
}
window.getInstDept=getInstDept;
/* ── getInstRank: 院校卡片排序权重（越小越靠前）── */
